import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    S = set(map(int, data[1:n+1]))

    max_x = 0
    for x in range(19):
        if (1 << x) > n:
            break
        if (1 << x) in S:
            max_x = x

    if max_x == 0:
        print(0)
        print(0)
        return

    def can_construct(x):
        size = 1 << x
        visited = [False] * size
        queue = deque([0])
        visited[0] = True
        permutation = [-1] * size
        permutation[0] = 0

        while queue:
            u = queue.popleft()
            for v in range(size):
                if not visited[v] and (u ^ v) in S:
                    visited[v] = True
                    permutation[v] = u
                    queue.append(v)

        return all(p != -1 for p in permutation)

    for x in range(max_x, -1, -1):
        if can_construct(x):
            size = 1 << x
            visited = [False] * size
            queue = deque([0])
            visited[0] = True
            permutation = [-1] * size
            permutation[0] = 0

            while queue:
                u = queue.popleft()
                for v in range(size):
                    if not visited[v] and (u ^ v) in S:
                        visited[v] = True
                        permutation[v] = u
                        queue.append(v)

            print(x)
            print(' '.join(map(str, permutation)))
            return

if __name__ == "__main__":
    main()
